    long long limit = *max_element(queries.begin(), queries.end());
    vector<int> best(limit + 1, 0);
    for (long long v = 1; v <= limit; v++) {
        int low = (int)v;
        for (long long s = 1; s * s <= v; s++) {
            low = min(low, best[v - s * s] + 1);
